* Java sample for invoking the API by using an image URL
```java
package demo;
import com.aliyun.ocr_api20210707.Client;
import com.aliyun.ocr_api20210707.models.*;
import com.aliyun.tea.TeaException;
import com.aliyun.teaopenapi.models.Config;
import com.google.gson.Gson;
public class Demo {
    public static void main(String[] args) throws Exception {
        final String endpoint = "ocr-api.cn-hangzhou.aliyuncs.com";
        final String accessKeyID = "Your AccessKeyID";
        final String accessKeySecret = "Your AccessKeySecret";
        final String imageUrl = "https://example.png";
        final Config config = new Config().setEndpoint(endpoint).setAccessKeyId(accessKeyID).setAccessKeySecret(accessKeySecret);
        Client client = new Client(config);
        RecognizeAllTextRequest request = new RecognizeAllTextRequest()
                .setType("Advanced")        // Specify the Type (this parameter is Required)
                .setUrl(imageUrl)           // Image URL
                .setOutputOricoord(true);   // Enable returning original image coordinates. You can configure more secondary parameters.
        // You can also specify more tertiary parameters in the request. For example, when Type=Advanced, you can set OutputCharInfo=true (to output character-level information).
        RecognizeAllTextRequest.RecognizeAllTextRequestAdvancedConfig advancedConfig = new RecognizeAllTextRequest.RecognizeAllTextRequestAdvancedConfig()
            .setOutputCharInfo(true);
        request.setAdvancedConfig(advancedConfig);
        try {
            RecognizeAllTextResponse response = client.recognizeAllText(request);
            System.out.println(new Gson().toJson(response.getBody().getData().toMap()));
        } catch (TeaException e) {
            System.out.println(e.getStatusCode());
        }
    }
}
```

* Java sample for invoking the API by uploading a local image
```java
package demo;
import com.aliyun.ocr_api20210707.Client;
import com.aliyun.ocr_api20210707.models.*;
import com.aliyun.tea.TeaException;
import com.aliyun.teaopenapi.models.Config;
import com.google.gson.Gson;
public class Demo {
    public static void main(String[] args) throws Exception {
        final String endpoint = "ocr-api.cn-hangzhou.aliyuncs.com";
        final String accessKeyID = "Your AccessKeyID";
        final String accessKeySecret = "Your AccessKeySecret";
        final Config config = new Config().setEndpoint(endpoint).setAccessKeyId(accessKeyID).setAccessKeySecret(accessKeySecret);
        final String localImageFileName = "~/example.png"; // Local image path
        Client client = new Client(config);
        try (InputStream imageStream = new FileInputStream(localImageFileName)) {
            RecognizeAllTextRequest request = new RecognizeAllTextRequest()
                    .setType("Advanced")        // Specify the Type (this parameter is Required)
                    .setBody(imageStream)       // Specify the local image path
                    .setOutputOricoord(true);   // Enable returning original image coordinates. You can configure more secondary parameters.
            // You can also specify more parameters in the request. For example, when Type=Advanced, you can set OutputCharInfo=true (to output character-level information).
            RecognizeAllTextRequest.RecognizeAllTextRequestAdvancedConfig advancedConfig = new RecognizeAllTextRequest.RecognizeAllTextRequestAdvancedConfig()
                    .setOutputCharInfo(true);
            request.setAdvancedConfig(advancedConfig);
            RecognizeAllTextResponse response = client.recognizeAllText(request);
            System.out.println(new Gson().toJson(response.getBody().getData().toMap()));
        } catch (TeaException e) {
            System.out.println(e.getStatusCode());
        }
    }
}
